CREATE OR REPLACE FUNCTION public.refresh_gym_expiration_events(g uuid, day date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.gym_access(g,'Settings') OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND gym_id=g AND role='Owner') THEN RAISE EXCEPTION 'Gym owner account required'; END IF; IF day<current_date-1 OR day>current_date+1 THEN RAISE EXCEPTION 'Invalid date'; END IF; INSERT INTO public.gym_owner_events(gym_id,event_key,type,description,page) SELECT g,'expiry:'||id||':'||(data->>'expiry')||':'||CASE WHEN (data->>'expiry')::date<day THEN 'expired' ELSE 'approaching' END,'Membership expiration',coalesce(data->>'name','Client')||CASE WHEN (data->>'expiry')::date<day THEN ' · Membership expired on ' ELSE ' · Membership expires on ' END||(data->>'expiry'),'/members' FROM public.gym_records WHERE gym_id=g AND kind='members' AND (data->>'expiry')::date<=day+7 ON CONFLICT(gym_id,event_key) DO NOTHING; END $$;
CREATE OR REPLACE FUNCTION public.disable_gym_account(g uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x public.gyms; dedicated boolean; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT * INTO x FROM public.gyms WHERE id=g FOR UPDATE; IF x.id IS NULL THEN RAISE EXCEPTION 'Gym unavailable'; END IF; dedicated:=EXISTS(SELECT 1 FROM public.profiles WHERE id=x.owner_id AND account_type='owner') AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=x.owner_id AND (role='super_admin' OR gym_id IS DISTINCT FROM g)) AND NOT EXISTS(SELECT 1 FROM public.gyms WHERE owner_id=x.owner_id AND id!=g AND deleted_at IS NULL) AND NOT EXISTS(SELECT 1 FROM public.gym_records WHERE client_id=x.owner_id AND gym_id!=g AND kind='members') AND NOT EXISTS(SELECT 1 FROM public.client_gym_links WHERE user_id=x.owner_id AND gym_id!=g); UPDATE public.gyms SET deleted_at=coalesce(deleted_at,now()) WHERE id=g; IF dedicated THEN UPDATE public.profiles SET disabled_at=coalesce(disabled_at,now()) WHERE id=x.owner_id; END IF; DELETE FROM public.client_gym_links WHERE gym_id=g; UPDATE public.staff_invitations SET status='Cancelled' WHERE gym_id=g AND status='Pending'; UPDATE public.owner_requests SET status='Rejected',decided_at=now(),decision_by=auth.uid() WHERE gym_id=g; RETURN jsonb_build_object('ownerId',x.owner_id,'disableOwner',dedicated); END $$;